// SETTINGS — tweak these (everything else is derived)
// ============================================================
const SETTINGS = {
  // ----- MODE -----
  displayMode: 'always-on',     // 'always-on' | 'random'
  position:    'corner',        // 'corner' | 'fullscreen'

  // ----- CORNER PLACEMENT -----
  corner:  'bottom-right',      // 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'
  marginX: 40,                  // px from left/right edge
  marginY: 40,                  // px from top/bottom edge

  // ----- SIZE & SHAPE -----
  sizePercent: 50,              // % of main video width
  shape:       'circle',        // 'circle' | 'square'

  // ----- ZOOM & CROP -----
  zoom:        1.0,             // 1.0 = no zoom; 1.5 / 2.0 = tighter framing
  cropOffsetX: 0,               // +right / -left of avatar source
  cropOffsetY: 0,               // +up / -down of avatar source

  // ----- RANDOM TIMING (only used when displayMode = 'random') -----
  overlayCoveragePercent: 30,   // % of video covered by avatar
  averageSegmentLength:   15,   // average seconds per appearance
  segmentLengthVariance:  0.3,  // ±30% around the average
  minGapBetweenSegments:  5,    // minimum quiet seconds between appearances
  startWithAvatar:        false,// true = video starts with avatar visible
  endWithAvatar:          false,// true = video ends with avatar visible

  // ----- ENCODING -----
  videoCodec: 'libx264', videoCRF: '20', videoPreset: 'medium',
  audioCodec: 'aac',     audioBitrate: '192k',
};


// ============================================================
// HELPERS
// ============================================================
const randRange = (min, max) => min + Math.random() * (max - min);
const round = (n, d = 3) => +n.toFixed(d);

function cornerXY(mX, mY) {
  return {
    'top-left':     `x=${mX}:y=${mY}`,
    'top-right':    `x=W-w-${mX}:y=${mY}`,
    'bottom-left':  `x=${mX}:y=H-h-${mY}`,
    'bottom-right': `x=W-w-${mX}:y=H-h-${mY}`,
  }[SETTINGS.corner] || `x=W-w-${mX}:y=H-h-${mY}`;
}

function buildSegmentPlan(duration) {
  const targetOverlay = duration * (SETTINGS.overlayCoveragePercent / 100);
  const avg = SETTINGS.averageSegmentLength;
  const N = Math.max(1, Math.round(targetOverlay / avg));

  const lengths = [];
  for (let i = 0; i < N; i++) {
    const v = SETTINGS.segmentLengthVariance;
    lengths.push(Math.max(1, avg * (1 + randRange(-v, v))));
  }
  const scale = targetOverlay / lengths.reduce((a, b) => a + b, 0);
  for (let i = 0; i < N; i++) lengths[i] *= scale;

  // Layout: [gap0][seg0][gap1][seg1]...[segN-1][gapN]
  // gap0=0 if startWithAvatar, gapN=0 if endWithAvatar, others >= minGapBetweenSegments
  const numGaps = N + 1;
  const minGap = SETTINGS.minGapBetweenSegments;
  const gapMins = new Array(numGaps).fill(minGap);
  if (SETTINGS.startWithAvatar) gapMins[0] = 0;
  if (SETTINGS.endWithAvatar)   gapMins[numGaps - 1] = 0;

  const totalSeg = lengths.reduce((a, b) => a + b, 0);
  const totalGap = duration - totalSeg;
  const minGapTotal = gapMins.reduce((a, b) => a + b, 0);
  if (totalGap < minGapTotal) {
    throw new Error(
      `Not enough room. Need ${minGapTotal.toFixed(1)}s of gaps, only ${totalGap.toFixed(1)}s available. ` +
      `Lower overlayCoveragePercent or minGapBetweenSegments.`
    );
  }

  const flexible = [];
  for (let i = 0; i < numGaps; i++) {
    const pinned = (SETTINGS.startWithAvatar && i === 0) ||
                   (SETTINGS.endWithAvatar   && i === numGaps - 1);
    if (!pinned) flexible.push(i);
  }
  const extra = totalGap - minGapTotal;
  const weights = flexible.map(() => Math.random());
  const wSum = weights.reduce((a, b) => a + b, 0) || 1;
  const gaps = new Array(numGaps).fill(0);
  flexible.forEach((idx, i) => {
    gaps[idx] = gapMins[idx] + (weights[i] / wSum) * extra;
  });

  const segments = [];
  let cursor = gaps[0];
  for (let i = 0; i < N; i++) {
    const len = lengths[i];
    const startTime = cursor;
    const endTime = startTime + len;
    const overlayStart = randRange(0, Math.max(0, duration - len));
    segments.push({
      startTime: round(startTime),
      endTime: round(endTime),
      length: round(len),
      overlayStart: round(overlayStart),
      overlayEnd: round(overlayStart + len),
    });
    cursor = endTime + gaps[i + 1];
  }
  return segments;
}

// ============================================================
// FILTER BUILDER
// ============================================================
function buildFilter(duration) {
  const z    = SETTINGS.zoom;
  const offX = SETTINGS.cropOffsetX;
  const offY = SETTINGS.cropOffsetY;
  const isFs = SETTINGS.position === 'fullscreen';
  const parts = [];

  // 1. Crop avatar with zoom + offset.
  if (isFs) {
    parts.push(
      `[1:v]crop='iw/${z}':'ih/${z}':` +
      `'(iw-iw/${z})/2+${offX}':'(ih-ih/${z})/2-${offY}'[ov_zoom]`
    );
  } else {
    parts.push(
      `[1:v]crop='min(iw,ih)/${z}':'min(iw,ih)/${z}':` +
      `'(iw-min(iw,ih)/${z})/2+${offX}':` +
      `'(ih-min(iw,ih)/${z})/2-${offY}'[ov_zoom]`
    );
  }

  // 2. Scale.
  if (isFs) {
    parts.push(
      `[ov_zoom][0:v]scale2ref=` +
      `w='iw*max(main_w/iw,main_h/ih)':` +
      `h='ih*max(main_w/iw,main_h/ih)'[ov_scaled][vmain]`
    );
  } else {
    const s = SETTINGS.sizePercent / 100;
    parts.push(
      `[ov_zoom][0:v]scale2ref=w='main_w*${s}':h='main_w*${s}'[ov_scaled][vmain]`
    );
  }

  // 3. Optional circle alpha mask (corner mode only).
  let avatarLabel = '[ov_scaled]';
  if (!isFs && SETTINGS.shape === 'circle') {
    parts.push(
      `[ov_scaled]format=yuva420p,geq=` +
      `lum='p(X,Y)':cb='p(X,Y)':cr='p(X,Y)':` +
      `a='if(gt(hypot(X-W/2,Y-H/2),min(W,H)/2),0,255)'[ov_shaped]`
    );
    avatarLabel = '[ov_shaped]';
  }

  // 4. Position string.
  const xy = isFs
    ? `x='(W-w)/2':y='(H-h)/2'`
    : cornerXY(SETTINGS.marginX, SETTINGS.marginY);

  // 5. Always-on or random placement.
  if (SETTINGS.displayMode === 'always-on') {
    parts.push(`[vmain]${avatarLabel}overlay=${xy}[vout]`);
    return { filterString: parts.join(';'), plan: null };
  }

  const segments = buildSegmentPlan(duration);
  const N = segments.length;
  const splitOuts = segments.map((_, i) => `[c${i}]`).join('');
  parts.push(`${avatarLabel}split=${N}${splitOuts}`);

  segments.forEach((s, i) => {
    parts.push(
      `[c${i}]trim=start=${s.overlayStart}:end=${s.overlayEnd},` +
      `setpts=PTS-STARTPTS+${s.startTime}/TB[r${i}]`
    );
  });

  let prev = '[vmain]';
  segments.forEach((s, i) => {
    const out = i === N - 1 ? '[vout]' : `[t${i}]`;
    parts.push(
      `${prev}[r${i}]overlay=${xy}:enable='between(t,${s.startTime},${s.endTime})'${out}`
    );
    prev = out;
  });

  const totalOverlay = segments.reduce((a, s) => a + s.length, 0);
  const plan = {
    numSegments: N,
    totalOverlayTime: round(totalOverlay, 2),
    actualCoveragePercent: round((totalOverlay / duration) * 100, 1),
    segments,
  };
  return { filterString: parts.join(';'), plan };
}

// ============================================================
// PAYLOAD BUILDER
// ============================================================
function buildPayload(mainUrl, avatarUrl, duration) {
  const { filterString, plan } = buildFilter(duration);
  const payload = {
    inputs: [
      { file_url: mainUrl },
      { file_url: avatarUrl },
    ],
    filters: [{ filter: filterString }],
    outputs: [
      {
        options: [
          { option: '-map', argument: '[vout]' },
          { option: '-map', argument: '0:a' },   // main audio only; avatar audio dropped
          { option: '-c:v', argument: SETTINGS.videoCodec },
          { option: '-crf', argument: SETTINGS.videoCRF },
          { option: '-preset', argument: SETTINGS.videoPreset },
          { option: '-c:a', argument: SETTINGS.audioCodec },
          { option: '-b:a', argument: SETTINGS.audioBitrate },
        ],
      },
    ],
    metadata: {
      thumbnail: true, filesize: true, duration: true, bitrate: true, encoder: true,
    },
    id: `avatar_${SETTINGS.displayMode}_${SETTINGS.position}_${Date.now()}`,
  };
  return { payload, plan };
}

