      `'(iw-iw/${z})/2+${offX}':'(ih-ih/${z})/2-${offY}'[ov_zoom]`
    );
  } else {
    parts.push(
      `[1:v]crop='min(iw,ih)/${z}':'min(iw,ih)/${z}':` +
      `'(iw-min(iw,ih)/${z})/2+${offX}':` +
      `'(ih-min(iw,ih)/${z})/2-${offY}'[ov_zoom]`
    );
  }

  // 2. Scale.
  if (isFs) {
    parts.push(
      `[ov_zoom][0:v]scale2ref=` +
      `w='iw*max(main_w/iw,main_h/ih)':` +
      `h='ih*max(main_w/iw,main_h/ih)'[ov_scaled][vmain]`
    );
  } else {
    const s = SETTINGS.sizePercent / 100;
    parts.push(
      `[ov_zoom][0:v]scale2ref=w='main_w*${s}':h='main_w*${s}'[ov_scaled][vmain]`
    );
  }

  // 3. Optional circle alpha mask (corner mode only).
  let avatarLabel = '[ov_scaled]';
  if (!isFs && SETTINGS.shape === 'circle') {
    parts.push(
      `[ov_scaled]format=yuva420p,geq=` +
      `lum='p(X,Y)':cb='p(X,Y)':cr='p(X,Y)':` +
      `a='if(gt(hypot(X-W/2,Y-H/2),min(W,H)/2),0,255)'[ov_shaped]`
    );
    avatarLabel = '[ov_shaped]';
  }

  // 4. Position string.
  const xy = isFs
    ? `x='(W-w)/2':y='(H-h)/2'`
    : cornerXY(SETTINGS.marginX, SETTINGS.marginY);

  // 5. Always-on or random placement.
  if (SETTINGS.displayMode === 'always-on') {
    parts.push(`[vmain]${avatarLabel}overlay=${xy}[vout]`);
    return { filterString: parts.join(';'), plan: null };
  }

  // Random mode — single overlay at native timing, gated by enable expression.
  // Avatar plays in sync with the main video (its frames at time t stay at time t),
  // so lips remain perfectly aligned with the main audio. We just show/hide.
  const segments = buildSegmentPlan(duration);
  const enableExpr = segments
    .map(s => `between(t,${s.startTime},${s.endTime})`)
    .join('+');
  parts.push(`[vmain]${avatarLabel}overlay=${xy}:enable='${enableExpr}'[vout]`);

  const totalOverlay = segments.reduce((a, s) => a + s.length, 0);
  const plan = {
    numSegments: segments.length,
    totalOverlayTime: round(totalOverlay, 2),
    actualCoveragePercent: round((totalOverlay / duration) * 100, 1),
    segments,
  };
  return { filterString: parts.join(';'), plan };
}

